// The Sales pack's tables (docs/plan.md §1.164 "The Sales area, first tables"; ARCHITECTURE §12.0
// rule 5: a match index that lasts and is searched is an area's, never one agent's). The client's
// synced CRM records as match keys, every decision matching a row to one of them, and the aliases a
// person's answers teach. Same tenancy rules as the platform's (CLAUDE.md invariant 1): every table
// has tenant_id, forced RLS on app.tenant_ids, and composite foreign keys (id, tenant_id) so a row
// can only point at the same client's rows.
//
// Migration 0072 creates them (generated by drizzle-kit from this file, which the db package's
// drizzle config lists, plus hand-written SQL for the grants, RLS, the history trigger and the pack
// comments). This file imports only drizzle-orm and the platform's schema at runtime, so
// drizzle-kit can load it.

import { agentVersion, appUser, connection, rawRecord, run, tenant } from "@countersign/db";
import { type SQL, sql } from "drizzle-orm";
import {
  type AnyPgColumn,
  check,
  foreignKey,
  index,
  integer,
  jsonb,
  numeric,
  pgTable,
  text,
  timestamp,
  unique,
  uuid,
  vector,
} from "drizzle-orm/pg-core";

// ── Allowed values ───────────────────────────────────────────────────────────────────────────────

/** What a row's decision is: one record, none of them (a new one), or a person decides. */
export const CRM_MATCH_DECISIONS = ["matched", "none", "unsure"] as const;
export type CrmMatchDecision = (typeof CRM_MATCH_DECISIONS)[number];

/**
 * How a decision was reached, in invariant 7's order: an exact key (email, phone, website domain),
 * an alias a person taught, similar text (trigrams), similar meaning (embeddings), the model's
 * choice among the candidates, or a person.
 */
export const CRM_MATCH_METHODS = ["key", "alias", "text", "meaning", "model", "human"] as const;
export type CrmMatchMethod = (typeof CRM_MATCH_METHODS)[number];

function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
  return sql`${column} in (${sql.raw(values.map((v) => `'${v}'`).join(", "))})`;
}

const id = () => uuid("id").primaryKey().default(sql`uuid_generate_v7()`);
const tenantId = () =>
  uuid("tenant_id")
    .notNull()
    .references(() => tenant.id);
const ts = (name: string) => timestamp(name, { withTimezone: true });
const createdAt = () => ts("created_at").notNull().defaultNow();
const hex64 = (column: AnyPgColumn) => sql`${column} ~ '^[0-9a-f]{64}$'`;

/** The normalised keys a row or a record is matched on (each absent when it has none). */
export interface CrmKeys {
  email?: string;
  phone?: string;
  domain?: string;
  company?: string;
  name?: string;
  deal?: string;
}

/**
 * One synced CRM record (a Zoho lead, contact, account or deal), as the Sales area matches on it:
 * its normalised keys, the text it is searched by, and that text's embedding. Built from the latest
 * raw record of the record and rebuilt when a newer one arrives; never another client's.
 */
export const crmRecordKey = pgTable(
  "crm_record_key",
  {
    id: id(),
    tenantId: tenantId(),
    connectionId: uuid("connection_id").notNull(),
    /** The connector's manifest id (`zoho_crm`): key building takes a mapper per connector. */
    connector: text("connector").notNull(),
    /** The connector's module (Zoho's `Leads`, `Contacts`, `Accounts`, `Deals`). */
    module: text("module").notNull(),
    /** The record's id in the client's tool. */
    externalId: text("external_id").notNull(),
    /** The raw record these keys were built from (invariant 10: a match's source). */
    rawRecordId: uuid("raw_record_id").notNull(),
    /** Lowercased. */
    email: text("email"),
    /** E.164. */
    phone: text("phone"),
    /** The website's domain, or the email's when it isn't a free mail service's. */
    domain: text("domain"),
    /** Normalised: lowercase words, legal suffixes (inc, llc, …) dropped. */
    companyName: text("company_name"),
    /** Normalised: lowercase words, first name first. */
    personName: text("person_name"),
    /** Normalised: lowercase words. */
    dealName: text("deal_name"),
    /** The record's values as written in the client's tool, for people (names, stage, amount). */
    display: jsonb("display").$type<Record<string, string>>().notNull().default({}),
    /** What it is searched by (trigrams, and the embedding): the fields the client matches on. */
    matchText: text("match_text").notNull(),
    /** sha256 (hex) of match_text. */
    matchHash: text("match_hash").notNull(),
    embedding: vector("embedding", { dimensions: 1024 }),
    /** sha256 (hex) of the text the embedding was made from: re-embedded when it isn't match_hash. */
    embeddedHash: text("embedded_hash"),
    embeddingModel: text("embedding_model"),
    createdAt: createdAt(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [
    unique("crm_record_key_id_tenant_key").on(t.id, t.tenantId),
    unique("crm_record_key_record_key").on(t.tenantId, t.connectionId, t.module, t.externalId),
    foreignKey({
      name: "crm_record_key_connection_fk",
      columns: [t.connectionId, t.tenantId],
      foreignColumns: [connection.id, connection.tenantId],
    }),
    foreignKey({
      name: "crm_record_key_raw_record_fk",
      columns: [t.rawRecordId, t.tenantId],
      foreignColumns: [rawRecord.id, rawRecord.tenantId],
    }),
    check("crm_record_key_module_check", sql`length(${t.module}) between 1 and 100`),
    check("crm_record_key_external_id_check", sql`length(${t.externalId}) between 1 and 200`),
    check("crm_record_key_email_check", sql`${t.email} is null or ${t.email} = lower(${t.email})`),
    check(
      "crm_record_key_phone_check",
      sql`${t.phone} is null or ${t.phone} ~ '^\\+[1-9][0-9]{6,14}$'`,
    ),
    check("crm_record_key_match_text_check", sql`length(${t.matchText}) <= 2000`),
    check("crm_record_key_match_hash_check", hex64(t.matchHash)),
    check(
      "crm_record_key_embedding_check",
      sql`(${t.embedding} is null) = (${t.embeddedHash} is null)
        and (${t.embeddedHash} is null or ${hex64(t.embeddedHash)})
        and (${t.embedding} is null or ${t.embeddingModel} is not null)`,
    ),
    // Step 1 (invariant 7): exact keys, per client.
    index("crm_record_key_email_idx").on(t.tenantId, t.email).where(sql`${t.email} is not null`),
    index("crm_record_key_phone_idx").on(t.tenantId, t.phone).where(sql`${t.phone} is not null`),
    index("crm_record_key_domain_idx").on(t.tenantId, t.domain).where(sql`${t.domain} is not null`),
    index("crm_record_key_module_idx").on(t.tenantId, t.module),
    // Step 3: candidates by similar text.
    index("crm_record_key_match_text_trgm_idx").using("gin", t.matchText.op("gin_trgm_ops")),
  ],
);

/**
 * Every decision about one input row (a spreadsheet's or a step's): the agent's, then a person's,
 * newest last. Never updated or deleted (trigger, 0072): a later decision is a new row with the
 * same batch and row.
 */
export const crmMatch = pgTable(
  "crm_match",
  {
    id: id(),
    tenantId: tenantId(),
    /** One per match: the rows matched together. A person's later decision keeps its row's batch. */
    batchId: uuid("batch_id").notNull(),
    runId: uuid("run_id"),
    /** The workflow step (node id) that matched, when a run's. */
    step: text("step"),
    /** The row's place in its batch, from 0. */
    rowIndex: integer("row_index").notNull(),
    /** The row's normalised key values (`CrmKeys`). */
    keys: jsonb("keys").$type<CrmKeys>().notNull(),
    decision: text("decision").$type<CrmMatchDecision>().notNull(),
    method: text("method").$type<CrmMatchMethod>().notNull(),
    /** The record, when matched. */
    recordKeyId: uuid("record_key_id"),
    connectionId: uuid("connection_id"),
    module: text("module"),
    externalId: text("external_id"),
    score: numeric("score", { precision: 4, scale: 3 }).notNull(),
    /** The candidates weighed: record, module, how found, score, why vetoed. */
    candidates: jsonb("candidates").$type<unknown[]>().notNull().default([]),
    /** The records the decision rests on (raw records, record keys; invariant 10). */
    sources: jsonb("sources").$type<string[]>().notNull().default([]),
    // DECISION: who decided is two typed columns with foreign keys, exactly one set, as
    // item_match's: the agent version that made it (invariant 10), or the person.
    agentVersionId: uuid("agent_version_id").references(() => agentVersion.id),
    decidedByUserId: uuid("decided_by_user_id").references(() => appUser.id),
    decidedAt: ts("decided_at").notNull().defaultNow(),
  },
  (t) => [
    unique("crm_match_id_tenant_key").on(t.id, t.tenantId),
    foreignKey({
      name: "crm_match_run_fk",
      columns: [t.runId, t.tenantId],
      foreignColumns: [run.id, run.tenantId],
    }),
    foreignKey({
      name: "crm_match_record_key_fk",
      columns: [t.recordKeyId, t.tenantId],
      foreignColumns: [crmRecordKey.id, crmRecordKey.tenantId],
    }),
    check("crm_match_decision_check", oneOf(t.decision, CRM_MATCH_DECISIONS)),
    check("crm_match_method_check", oneOf(t.method, CRM_MATCH_METHODS)),
    check("crm_match_row_index_check", sql`${t.rowIndex} >= 0`),
    check("crm_match_score_check", sql`${t.score} between 0 and 1`),
    check(
      "crm_match_record_check",
      sql`(${t.decision} = 'matched') = (${t.recordKeyId} is not null)
        and num_nonnulls(${t.recordKeyId}, ${t.connectionId}, ${t.module}, ${t.externalId}) in (0, 4)`,
    ),
    check(
      "crm_match_decided_by_check",
      sql`num_nonnulls(${t.agentVersionId}, ${t.decidedByUserId}) = 1
        and (${t.method} = 'human') = (${t.decidedByUserId} is not null)`,
    ),
    check("crm_match_step_check", sql`${t.step} is null or length(${t.step}) between 1 and 200`),
    index("crm_match_batch_idx").on(t.tenantId, t.batchId, t.rowIndex, t.decidedAt),
    index("crm_match_run_idx").on(t.tenantId, t.runId),
    index("crm_match_record_key_idx").on(t.tenantId, t.recordKeyId),
  ],
);

/**
 * A person's answer, so the same row matches by itself next time: the row's normalised key values
 * (by their hash) → the record, in one module of one connection. Made only by a person's decision
 * (method `human`), with who and when; a later answer for the same values replaces it.
 */
export const crmAlias = pgTable(
  "crm_alias",
  {
    id: id(),
    tenantId: tenantId(),
    connectionId: uuid("connection_id").notNull(),
    module: text("module").notNull(),
    /** sha256 (hex) of the canonical JSON of `keys`. */
    keyHash: text("key_hash").notNull(),
    keys: jsonb("keys").$type<CrmKeys>().notNull(),
    recordKeyId: uuid("record_key_id").notNull(),
    externalId: text("external_id").notNull(),
    /** The person's decision that taught it. */
    matchId: uuid("match_id").notNull(),
    createdByUserId: uuid("created_by_user_id")
      .notNull()
      .references(() => appUser.id),
    createdAt: createdAt(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [
    unique("crm_alias_keys_key").on(t.tenantId, t.connectionId, t.module, t.keyHash),
    foreignKey({
      name: "crm_alias_connection_fk",
      columns: [t.connectionId, t.tenantId],
      foreignColumns: [connection.id, connection.tenantId],
    }),
    foreignKey({
      name: "crm_alias_record_key_fk",
      columns: [t.recordKeyId, t.tenantId],
      foreignColumns: [crmRecordKey.id, crmRecordKey.tenantId],
    }),
    foreignKey({
      name: "crm_alias_match_fk",
      columns: [t.matchId, t.tenantId],
      foreignColumns: [crmMatch.id, crmMatch.tenantId],
    }),
    check("crm_alias_key_hash_check", hex64(t.keyHash)),
    check("crm_alias_keys_check", sql`jsonb_typeof(${t.keys}) = 'object' and ${t.keys} <> '{}'`),
    index("crm_alias_record_key_idx").on(t.tenantId, t.recordKeyId),
  ],
);

/** The pack's tenant tables, in the order its RLS tests walk them. */
export const SALES_TABLES = ["crm_record_key", "crm_match", "crm_alias"] as const;
export type SalesTable = (typeof SALES_TABLES)[number];
